<?php require_once __DIR__ . '/../bootstrap.php'; require_auth('admin'); $stats=[]; foreach(['users'=>'SELECT COUNT(*) FROM users','active'=>'SELECT COUNT(*) FROM users WHERE status="active"','logs'=>'SELECT COUNT(*) FROM log_entries','today'=>'SELECT COUNT(*) FROM log_entries WHERE log_date=CURDATE()','week'=>'SELECT COUNT(*) FROM log_entries WHERE log_date >= DATE_SUB(CURDATE(), INTERVAL 6 DAY)','month'=>'SELECT COUNT(*) FROM log_entries WHERE YEAR(log_date)=YEAR(CURDATE()) AND MONTH(log_date)=MONTH(CURDATE())'] as $key=>$sql){$stats[$key]=(int)$pdo->query($sql)->fetchColumn();} respond(true,'',['stats'=>$stats]);
